import type {
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { decodeReservation, isId, isQuantity, isRecord, isRevision, isUnits } from "./validation";
import { error } from "./reservation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadResult<T> =
  | { kind: "found"; value: T }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

function parseDecimalText(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^(0|[1-9][0-9]*)$/.test(value)) return undefined;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : undefined;
}

function decodeStockRow(value: unknown, requestedKey: string): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey) || value.itemKey !== requestedKey) return undefined;

  const totalUnits = parseDecimalText(value.onHandText);
  const reservedUnits = parseDecimalText(value.heldText);
  const revision = parseDecimalText(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) {
    return undefined;
  }

  return { sku: value.itemKey, totalUnits, reservedUnits, revision };
}

function decodeReservationRow(value: unknown, requestedKey: string): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || value.bookingKey !== requestedKey ||
      !isId(value.itemKey)) {
    return undefined;
  }

  const quantity = parseDecimalText(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;

  return {
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  };
}

function encodeStockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: String(stock.totalUnits),
    heldText: String(stock.reservedUnits),
    revisionText: String(stock.revision),
  };
}

function encodeReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: String(reservation.quantity),
  };
}

function readEnvelopeValue(raw: unknown): { kind: "found"; value: unknown } | { kind: "missing" } | { kind: "unavailable" } {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") return { kind: "unavailable" };
  if (raw.ok) {
    return Object.hasOwn(raw, "value") ? { kind: "found", value: raw.value } : { kind: "unavailable" };
  }
  if (!isRecord(raw.error) || typeof raw.error.reason !== "string") return { kind: "unavailable" };
  if (raw.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<ReadResult<Stock>> {
  const raw = await storage.read({ collection: "inventory", key: sku });
  const envelope = readEnvelopeValue(raw);
  if (envelope.kind !== "found") return envelope;

  const stock = decodeStockRow(envelope.value, sku);
  return stock ? { kind: "found", value: stock } : { kind: "unavailable" };
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<ReadResult<Reservation>> {
  const raw = await storage.read({ collection: "reservations", key: reservationId });
  const envelope = readEnvelopeValue(raw);
  if (envelope.kind !== "found") return envelope;

  const reservation = decodeReservationRow(envelope.value, reservationId);
  return reservation ? { kind: "found", value: reservation } : { kind: "unavailable" };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock.kind === "missing") return error(404, "stock_not_found");
          if (stock.kind === "unavailable") return error(500, "storage_unavailable");
          return {
            status: 200,
            body: {
              sku: stock.value.sku,
              totalUnits: stock.value.totalUnits,
              reservedUnits: stock.value.reservedUnits,
              availableUnits: stock.value.totalUnits - stock.value.reservedUnits,
            },
          };
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing.kind === "found"
            ? reservationResponse(200, existing.value)
            : error(404, "reservation_not_found");
        }

        if (existing.kind === "found") {
          const decoded = decodeReservation(existing.value);
          if (!decoded) return error(500, "storage_unavailable");
          return decoded.sku === command.sku && decoded.quantity === command.quantity
            ? reservationResponse(200, decoded)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock.kind === "missing") return error(404, "stock_not_found");
        if (stock.kind === "unavailable") return error(500, "storage_unavailable");
        if (stock.value.totalUnits - stock.value.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const nextRevision = stock.value.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const nextStock: Stock = {
          ...stock.value,
          reservedUnits: stock.value.reservedUnits + command.quantity,
          revision: nextRevision,
        };
        const reservationRow = encodeReservationRow(reservation);
        const outcome = await storage.commitBatch({
          expectedRevisionText: String(stock.value.revision),
          stockRow: encodeStockRow(nextStock),
          reservationRow,
          outboxRows: [{
            key: "reservation.created:" + reservation.reservationId,
            category: "reservation",
            name: "created",
            payload: reservationRow,
          }],
        });

        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

