import type { Service, ServiceResponse, StockReportSource } from "./types";
import { isId, isRecord, isUnits } from "./validation";
import { error } from "./reservation";

type LowStockCommand = { op: "lowStock"; belowUnits: number };

function parseCommand(raw: unknown): LowStockCommand | undefined {
  if (!isRecord(raw) || raw.op !== "lowStock" || !isUnits(raw.belowUnits)) {
    return undefined;
  }
  return { op: "lowStock", belowUnits: raw.belowUnits };
}

function decodeSnapshotRow(value: unknown): { sku: string; totalUnits: number; reservedUnits: number } | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits) {
    return undefined;
  }
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
  };
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        const snapshot = await source.readSnapshot();
        if (!Array.isArray(snapshot)) return error(500, "storage_unavailable");

        const seen = new Set<string>();
        const items: Array<{ sku: string; availableUnits: number }> = [];
        for (const rawRow of snapshot) {
          const row = decodeSnapshotRow(rawRow);
          if (!row || seen.has(row.sku)) return error(500, "storage_unavailable");
          seen.add(row.sku);

          const availableUnits = row.totalUnits - row.reservedUnits;
          if (availableUnits < command.belowUnits) {
            items.push({ sku: row.sku, availableUnits });
          }
        }

        items.sort((left, right) => left.sku < right.sku ? -1 : left.sku > right.sku ? 1 : 0);
        return { status: 200, body: { items } };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

